def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    out = [row[:] for row in grid]
    # A diagonal matching pair extends outward from both ends, stopping at
    # the first non-background object or the grid boundary. Ignore a ray
    # when it has fewer than two background cells available.
    pairs = set()
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v == bg:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                rr, cc = r + dr, c + dc
                if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == v:
                    pairs.add((r, c, dr, dc, v))
    for r, c, dr, dc, v in pairs:
        for sr, sc, ar, ac in ((-dr, -dc, r, c), (dr, dc, r + dr, c + dc)):
            cells = []
            rr, cc = ar, ac
            while 0 <= rr + sr < h and 0 <= cc + sc < w:
                rr += sr
                cc += sc
                if grid[rr][cc] != bg:
                    break
                cells.append((rr, cc))
            if len(cells) >= 2:
                for rr, cc in cells:
                    out[rr][cc] = v
    return out

